function loadState(){try{const saved=JSON.parse(localStorage.getItem(STATE_KEY)||'{}'),merged=deepMerge(structuredClone(defaultState),saved);merged.version=3;return merged}catch{return structuredClone(defaultState)}}
function deepMerge(base,extra){if(!extra||typeof extra!=='object')return base;for(const[k,v]of Object.entries(extra)){if(v&&typeof v==='object'&&!Array.isArray(v)&&base[k]&&typeof base[k]==='object'&&!Array.isArray(base[k]))base[k]=deepMerge(base[k],v);else base[k]=v}return base}
function save(){localStorage.setItem(STATE_KEY,JSON.stringify(state))}
function uid(p='id'){return p+Math.random().toString(36).slice(2,9)}
function iconMarkup(k){return ICONS[k]||ICONS.sparkle}
function getTask(id){return state.library.find(t=>t.id===id)}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast._id);toast._id=setTimeout(()=>el.classList.remove('show'),2200)}
function isStandalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function startOfWeek(d){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-x.getDay());return x}
function scheduleDays(item){const raw=Array.isArray(item.days)&&item.days.length?item.days:[item.day];return [...new Set(raw.filter(v=>v!==undefined&&v!==null).map(Number))]}
function scheduleTimes(item){const raw=Array.isArray(item.times)&&item.times.length?item.times:[item.time||'18:00'];return [...new Set(raw.filter(Boolean))].sort()}
function scheduleAssignees(item){if(Array.isArray(item.assigneeIds)&&item.assigneeIds.length)return [...new Set(item.assigneeIds)];return item.memberId?[item.memberId]:[]}
function firstDueDate(item,targetDay=scheduleDays(item)[0]??new Date().getDay()){const base=new Date(item.startDate||Date.now());base.setHours(0,0,0,0);while(base.getDay()!==Number(targetDay))base.setDate(base.getDate()+1);return base}
function occursOn(item,date){const d=new Date(date);d.setHours(0,0,0,0);const day=d.getDay();if(!scheduleDays(item).includes(day))return false;const first=firstDueDate(item,day);if(d<first)return false;const days=Math.round((d-first)/86400000);if(item.repeat==='once')return dateKey(d)===dateKey(first);if(item.repeat==='biweekly')return days%14===0;if(item.repeat==='monthly')return Math.ceil(d.getDate()/7)===Math.ceil(first.getDate()/7);return days%7===0}
function completionKey(item,date,mode=item.mode,time=item.occurrenceTime||''){return `${item.id}:${dateKey(date)}:${mode}:${time||'day'}`}
function legacyCompletionKey(item,date,mode=item.mode){return `${item.id}:${dateKey(date)}:${mode}`}
function completionFor(item,date,mode=item.mode,time=item.occurrenceTime||''){const key=completionKey(item,date,mode,time);return state.completions[key]||state.completions[legacyCompletionKey(item,date,mode)]||{done:[],all:false}}
function isComplete(item,date,mode=item.mode,time=item.occurrenceTime||''){return !!completionFor(item,date,mode,time).all}
function setNight(){document.body.classList.toggle('night',!!state.settings.night);$('#themeToggle')?.setAttribute('aria-pressed',String(!!state.settings.night))}
async function hashPin(pin){const data=new TextEncoder().encode(pin);const hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}

function setupGate(){if(isStandalone()){showApp()}else{showGate()}}
function showGate(){ $('#browserGate').classList.remove('hidden');$('#app').classList.add('hidden');const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);$('#installSteps').innerHTML=ios?'<b>Install HouseMade</b>Tap <strong>Share</strong> → <strong>Add to Home Screen</strong> → <strong>Add</strong>.':'<b>Install HouseMade</b>Use your browser menu and choose <strong>Install app</strong> or <strong>Add to Home Screen</strong>.'; }
function showApp(){ $('#browserGate').classList.add('hidden');$('#app').classList.remove('hidden');setNight();renderAll(); if(!state.profile){$('#onboarding').classList.remove('hidden');return}if(state.profile.pinHash&&sessionStorage.getItem('hm-unlocked')!=='1'){showLock();return}startGreeting();startReminderChecker() }
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('#installBtn').classList.remove('hidden')});
$('#installBtn').onclick=async()=>{if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;$('#installBtn').classList.add('hidden')};

function startGreeting(){if(!state.profile)return;$('#greetingHey').textContent=`Hey ${state.profile.firstName},`;$('#greetingMake').textContent='let’s get this house made…';$('#greetingTogether').textContent='together!';const card=$('#greetingCard');card.classList.remove('play');void card.offsetWidth;card.classList.add('play');createParticles($('#greetingParticles'),28);if(state.settings.sound)chime('shimmer')}
function createParticles(container,count){container.innerHTML='';for(let i=0;i<count;i++){const p=document.createElement('i');p.style.left=`${-15+Math.random()*35}%`;p.style.top=`${20+Math.random()*70}%`;p.style.animationDelay=`${Math.random()*.8}s`;p.style.animationDuration=`${2+Math.random()*1.4}s`;container.appendChild(p)}}
function showLock(){ $('#lockName').textContent=state.profile.firstName;$('#lockScreen').classList.remove('hidden');$('#unlockPin').value='';$('#unlockError').textContent='';setTimeout(()=>$('#unlockPin').focus(),180)}

function renderAll(){renderSelectors();renderPlanner();renderUpNext();renderProgressBoard();renderPromptQueue();renderScheduleList();renderMembers();renderTasks();renderPresetLibrary();renderSettings();updateNotificationDot()}
function renderSelectors(){fillSelect($('#schedTask'),state.library.map(t=>[t.id,t.name]));renderPlannerAssignees();renderPlannerDays();$$('.segment').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view))}
function fillSelect(select,items){if(!select)return;const prev=select.value;select.innerHTML='';items.forEach(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;select.appendChild(o)});if([...select.options].some(o=>o.value===prev))select.value=prev}
function plannerAnchor(){const now=new Date();now.setHours(0,0,0,0);const offset=Number(state.plannerOffset||0);if(state.view==='day')now.setDate(now.getDate()+offset);else if(state.view==='week')now.setDate(now.getDate()+offset*7);else now.setMonth(now.getMonth()+offset);return now}
function plannerDates(){const anchor=plannerAnchor();if(state.view==='day')return[anchor];if(state.view==='week'){const s=startOfWeek(anchor);return Array.from({length:7},(_,i)=>{const d=new Date(s);d.setDate(s.getDate()+i);return d})}const first=new Date(anchor.getFullYear(),anchor.getMonth(),1);const grid=startOfWeek(first);return Array.from({length:42},(_,i)=>{const d=new Date(grid);d.setDate(grid.getDate()+i);return d})}
function occurrenceListForDate(date){const out=[];state.schedule.filter(s=>occursOn(s,date)).forEach(item=>scheduleTimes(item).forEach(time=>out.push({item,date:new Date(date),time})));return out.sort((a,b)=>a.time.localeCompare(b.time))}
function plannerLabel(dates){if(state.view==='day')return dates[0].toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'});if(state.view==='week')return `${dates[0].toLocaleDateString(undefined,{day:'numeric',month:'short'})} – ${dates[dates.length-1].toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}`;const a=plannerAnchor();return a.toLocaleDateString(undefined,{month:'long',year:'numeric'})}
function renderPlanner(){const wrap=$('#planner');if(!wrap)return;const dates=plannerDates();$('#periodLabel').textContent=plannerLabel(dates);const total=dates.reduce((n,d)=>n+occurrenceListForDate(d).length,0);$('#plannerSummary').textContent=`${total} ${total===1?'entry':'entries'}`;wrap.innerHTML='';if(state.view==='month'){wrap.className='planner diary month';const activeMonth=plannerAnchor().getMonth();dates.forEach(d=>{const day=document.createElement('article');day.className='planner-day month-cell'+(dateKey(d)===dateKey(new Date())?' today':'');if(d.getMonth()!==activeMonth)day.classList.add('outside-month');const title=document.createElement('div');title.className='day-title';title.innerHTML=`<b>${d.toLocaleDateString(undefined,{weekday:'short'})}</b><span>${d.getDate()}</span>`;day.appendChild(title);occurrenceListForDate(d).slice(0,4).forEach(({item,time},i)=>day.appendChild(choreChip(item,d,time,i)));const extra=occurrenceListForDate(d).length-4;if(extra>0){const more=document.createElement('small');more.className='calendar-more';more.textContent=`+${extra} more`;day.appendChild(more)};wrap.appendChild(day)});return}
 const hours=Array.from({length:17},(_,i)=>i+6);wrap.className='planner diary time-diary';const diary=document.createElement('div');diary.className='diary-grid';diary.style.setProperty('--diary-days',String(dates.length));const corner=document.createElement('div');corner.className='diary-corner';corner.textContent='TIME';diary.appendChild(corner);dates.forEach(d=>{const h=document.createElement('div');h.className='diary-day-head'+(dateKey(d)===dateKey(new Date())?' today':'');h.innerHTML=`<b>${d.toLocaleDateString(undefined,{weekday:'short'})}</b><span>${d.getDate()}</span>`;diary.appendChild(h)});hours.forEach(hour=>{const label=document.createElement('div');label.className='diary-time';label.textContent=`${String(hour).padStart(2,'0')}:00`;diary.appendChild(label);dates.forEach(d=>{const cell=document.createElement('div');cell.className='diary-cell';occurrenceListForDate(d).filter(o=>Number(o.time.split(':')[0])===hour).forEach(({item,time},i)=>cell.appendChild(diaryEvent(item,d,time,i)));diary.appendChild(cell)})});wrap.appendChild(diary)}
function diaryEvent(item,date,time,delay=0){const t=getTask(item.taskId),names=scheduleAssignees(item).map(id=>state.members.find(m=>m.id===id)?.name).filter(Boolean);const b=document.createElement('button');b.className='diary-event'+(isComplete(item,date,item.mode,time)?' completed':'');b.style.setProperty('--task',t?.color||'#B59EE2');b.style.animationDelay=`${Math.min(delay*.03,.2)}s`;b.innerHTML=`<span>${time}</span><b></b><small></small>`;b.querySelector('b').textContent=t?.name||'Task';b.querySelector('small').textContent=`${item.mode==='deep'?'Deep':'Quick'}${names.length?' · '+names.join(', '):''}`;b.onclick=()=>openTask(item,date,time);return b}
function choreChip(item,date,time,delay=0){const t=getTask(item.taskId),names=scheduleAssignees(item).map(id=>state.members.find(m=>m.id===id)?.name).filter(Boolean);const b=document.createElement('button');b.className='chore-chip'+(isComplete(item,date,item.mode,time)?' completed':'');b.style.setProperty('--task',t?.color||'#B59EE2');b.style.animationDelay=`${Math.min(delay*.025,.35)}s`;b.innerHTML=`<span class="chip-icon">${isComplete(item,date,item.mode,time)?'✓':iconMarkup(t?.icon)}</span><span class="chip-copy"><b></b><small></small></span>`;b.querySelector('b').textContent=t?.name||'Task';b.querySelector('small').textContent=`${time} · ${item.mode==='deep'?'Deep':'Quick'}${names.length?' · '+names.join(', '):''}`;b.onclick=()=>openTask(item,date,time);return b}
function nextOccurrences(limit=5){const out=[],start=new Date(),now=new Date();start.setHours(0,0,0,0);for(let i=0;i<90;i++){const d=new Date(start);d.setDate(start.getDate()+i);occurrenceListForDate(d).forEach(o=>{const stamp=new Date(d);const[h,m]=o.time.split(':').map(Number);stamp.setHours(h,m,0,0);if(stamp>=now&&!isComplete(o.item,o.date,o.item.mode,o.time))out.push({...o,stamp})})}out.sort((a,b)=>a.stamp-b.stamp);return out.slice(0,limit)}
function roomSceneMarkup(task){return `<span class="scene-spark">✦</span><span class="scene-icon">${iconMarkup(task.icon)}</span><i></i><i></i>`}
function renderUpNext(){const wrap=$('#upNext');if(!wrap)return;wrap.innerHTML='';const next=nextOccurrences(4);if(!next.length){wrap.innerHTML='<div class="surface muted">Nothing coming up. The house has suspiciously little to complain about.</div>';return}next.forEach(({item,date,time})=>{const t=getTask(item.taskId),names=scheduleAssignees(item).map(id=>state.members.find(m=>m.id===id)?.name).filter(Boolean);const b=document.createElement('button');b.className='up-card pro-up-card';b.style.setProperty('--task',t.color);b.innerHTML=`<span class="up-scene">${roomSceneMarkup(t)}</span><div><b></b><small></small></div><span class="up-arrow">›</span>`;b.querySelector('b').textContent=t.name;b.querySelector('small').textContent=`${date.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})} · ${time} · ${item.mode==='deep'?'Deep':'Quick'}${names.length?' · '+names.join(', '):''}`;b.onclick=()=>openTask(item,date,time);wrap.appendChild(b)})}
function currentWeekOccurrences(){const s=startOfWeek(new Date()),out=[];for(let i=0;i<7;i++){const d=new Date(s);d.setDate(s.getDate()+i);occurrenceListForDate(d).forEach(o=>out.push(o))}return out}
function renderProgressBoard(){if(!$('#progressPercent'))return;const occ=currentWeekOccurrences(),done=occ.filter(o=>isComplete(o.item,o.date,o.item.mode,o.time)),pct=occ.length?Math.round(done.length/occ.length*100):0,rooms=new Set(done.map(o=>o.item.taskId)).size;$('#progressPercent').textContent=`${pct}%`;$('#progressDone').textContent=done.length;$('#progressRooms').textContent=rooms;$('#progressLeft').textContent=Math.max(0,occ.length-done.length);$('#progressFill').style.width=`${pct}%`;$('#progressDuster').style.left=`calc(${Math.max(2,Math.min(96,pct))}% - 22px)`;const msg=pct===100?'House conquered. You may now admire your work dramatically.':pct>=70?'The mess is losing confidence. Keep going.':pct>=35?'Momentum acquired. The house has noticed.':pct>0?'That first bit counts more than it looks.':'A clean slate starts with one tiny swipe.';$('#progressMessage').textContent=occ.length?msg:'Add a few tasks in Planner and your weekly progress story will appear here.'}
function promptQueueEntries(limit=12){const rows=[];nextOccurrences(80).forEach(o=>{if(o.item.notify===false||isComplete(o.item,o.date,o.item.mode,o.time))return;scheduleAssignees(o.item).forEach(id=>{const member=state.members.find(m=>m.id===id);if(member)rows.push({...o,member,queueId:`${o.item.id}:${dateKey(o.date)}:${o.time}:${id}`})})});return rows.slice(0,limit)}
function renderPromptQueue(){const wrap=$('#promptQueue');if(!wrap)return;wrap.innerHTML='';const rows=promptQueueEntries(10);$('#promptQueueCount').textContent=rows.length?`${rows.length} ready`:'Clear';if(!rows.length){wrap.innerHTML='<div class="queue-empty">Assign a planner task to a family member and its prompt will appear here automatically.</div>';return}rows.forEach(row=>{const t=getTask(row.item.taskId),status=state.promptStatus?.[row.queueId]||'ready',card=document.createElement('div');card.className='queue-row';card.style.setProperty('--task',t?.color||'#B59EE2');card.innerHTML=`<span class="queue-icon">${iconMarkup(t?.icon)}</span><div class="queue-copy"><b></b><span></span><small></small></div><button class="queue-action">${status==='copied'?'Copied ✓':'Prepare →'}</button>`;card.querySelector('b').textContent=`${row.member.name} · ${t?.name||'Chore'}`;card.querySelector('span').textContent=`${row.date.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})} · ${row.time}`;card.querySelector('small').textContent=row.item.note||`${row.item.mode==='deep'?'Deep Clean':'Quick Clean'} reminder`;card.querySelector('button').onclick=()=>openReminder(row.member,{taskName:t?.name||'HouseMade chore',date:row.date,time:row.time,queueId:row.queueId});wrap.appendChild(card)})}
function renderScheduleList(){const wrap=$('#scheduleList');wrap.innerHTML='';if(!state.schedule.length){wrap.innerHTML='<div class="muted">No planner tasks yet.</div>';return}state.schedule.forEach(item=>{const t=getTask(item.taskId),names=scheduleAssignees(item).map(id=>state.members.find(m=>m.id===id)?.name).filter(Boolean),row=document.createElement('div');row.className='list-row planner-foundation-row';row.innerHTML=`<div class="list-symbol" style="background:${t?.color||'#B59EE2'}">${iconMarkup(t?.icon)}</div><div class="list-copy"><b></b><span></span><small></small></div><div class="list-actions"><button class="tiny-btn danger-btn">Remove</button></div>`;row.querySelector('.list-copy b').textContent=`${t?.name||'Task'} · ${item.mode==='deep'?'Deep':'Quick'}`;row.querySelector('.list-copy span').textContent=`${scheduleDays(item).map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]).join(', ')} · ${scheduleTimes(item).join(' / ')} · ${item.repeat==='once'?'one week':item.repeat}`;row.querySelector('.list-copy small').textContent=names.length?`Assigned: ${names.join(', ')}`:'Household task';row.querySelector('button').onclick=()=>{state.schedule=state.schedule.filter(x=>x.id!==item.id);save();renderAll();toast('Planner task removed')};wrap.appendChild(row)})}
function renderMembers(){const wrap=$('#memberList');wrap.innerHTML='';if(!state.members.length){wrap.innerHTML='<div class="surface muted">Add family members to assign chores and generate friendly prompts.</div>';return}state.members.forEach(m=>{const row=document.createElement('div');row.className='list-row';row.innerHTML=`<div class="avatar">${(m.name[0]||'?').toUpperCase()}</div><div class="list-copy"><b></b><span></span></div><div class="list-actions"><button class="tiny-btn prompt">Prompt</button><button class="tiny-btn danger-btn remove">Remove</button></div>`;row.querySelector('b').textContent=m.name;row.querySelector('span').textContent=`${CHANNEL_LABELS[m.channel]||m.channel}${m.contact?' · '+m.contact:''}`;row.querySelector('.prompt').onclick=()=>openReminder(m);row.querySelector('.remove').onclick=()=>{state.members=state.members.filter(x=>x.id!==m.id);state.schedule=state.schedule.map(s=>({...s,memberId:s.memberId===m.id?null:s.memberId,assigneeIds:Array.isArray(s.assigneeIds)?s.assigneeIds.filter(id=>id!==m.id):s.assigneeIds}));save();renderAll();toast(`${m.name} removed`)};wrap.appendChild(row)})}
function renderTasks(){const wrap=$('#taskLibrary');wrap.innerHTML='';state.library.forEach(t=>{const b=document.createElement('button');b.className='task-card';b.style.setProperty('--task',t.color);b.innerHTML=`<span class="task-card-icon">${iconMarkup(t.icon)}</span><div><b></b><small></small></div><span>›</span>`;b.querySelector('b').textContent=t.name;b.querySelector('small').textContent=`${t.quick.length} quick · ${t.deep.length} deep`;b.onclick=()=>editTask(t.id);wrap.appendChild(b)})}
function renderPresetLibrary(){const wrap=$('#presetLibrary');wrap.innerHTML='';state.presetItems.forEach(item=>{const chip=document.createElement('span');chip.className='preset-pill';const label=document.createElement('span');label.textContent=item;const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label',`Remove ${item}`);del.onclick=()=>{state.presetItems=state.presetItems.filter(x=>x!==item);save();renderPresetLibrary();toast('Preset removed')};chip.append(label,del);wrap.appendChild(chip)})}
function renderSettings(){if(!state.profile)return;$('#settingsName').value=state.profile.firstName||'';$('#settingsHouse').value=state.householdName||'Our House';$('#musicUrl').value=state.settings.musicUrl||'';$('#defaultTimer').value=state.settings.defaultTimer||15;$('#soundToggle').setAttribute('aria-pressed',String(!!state.settings.sound));$('#themeToggle').setAttribute('aria-pressed',String(!!state.settings.night));setNight()}
function updateNotificationDot(){const upcoming=nextOccurrences(4).some(({item,date})=>!isComplete(item,date));$('#notificationDot').classList.toggle('hidden',!upcoming)}

