function renderPlannerDays(){const wrap=$('#schedDays');if(!wrap)return;const selected=new Set($$('#schedDays input:checked').map(x=>Number(x.value)));wrap.innerHTML='';['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach((label,day)=>{const l=document.createElement('label');l.className='multi-chip';l.innerHTML=`<input type="checkbox" value="${day}"><span>${label}</span>`;const input=l.querySelector('input');input.checked=selected.size?selected.has(day):day===new Date().getDay();wrap.appendChild(l)})}
function renderPlannerAssignees(){const wrap=$('#schedAssignees');if(!wrap)return;const selected=new Set($$('#schedAssignees input:checked').map(x=>x.value));wrap.innerHTML='';if(!state.members.length){wrap.innerHTML='<span class="muted mini-note">No family members yet — this will remain a household task.</span>';return}state.members.forEach(m=>{const l=document.createElement('label');l.className='multi-chip person-chip';l.innerHTML=`<input type="checkbox" value="${m.id}"><span>${m.name}</span>`;l.querySelector('input').checked=selected.has(m.id);wrap.appendChild(l)})}
function renderPlannerTimes(){const wrap=$('#plannerTimeChips');if(!wrap)return;wrap.innerHTML='';plannerTimesDraft.forEach(time=>{const b=document.createElement('button');b.className='time-chip';b.innerHTML=`<span>${time}</span><i>×</i>`;b.onclick=()=>{if(plannerTimesDraft.length===1){toast('Keep at least one time');return}plannerTimesDraft=plannerTimesDraft.filter(x=>x!==time);renderPlannerTimes()};wrap.appendChild(b)})}
function openPlannerAdd(){plannerTimesDraft=['18:00'];$('#schedDays').innerHTML='';$('#schedAssignees').innerHTML='';$('#plannerTimeInput').value='18:00';$('#schedStart').value=dateKey(new Date());$('#schedRepeat').value='weekly';$('#schedMode').value='quick';$('#schedNote').value='';$('#schedNotify').checked=true;renderPlannerDays();renderPlannerAssignees();renderPlannerTimes();$('#plannerAddModal').classList.remove('hidden');if(state.settings.sound)chime('soft')}
$('#openPlannerAdd').onclick=openPlannerAdd;$('#closePlannerAdd').onclick=()=>$('#plannerAddModal').classList.add('hidden');
$('#addPlannerTime').onclick=()=>{const v=$('#plannerTimeInput').value||'18:00';if(!plannerTimesDraft.includes(v))plannerTimesDraft.push(v);plannerTimesDraft.sort();renderPlannerTimes();if(state.settings.sound)chime('soft')};
$('#addSchedule').onclick=()=>{const taskId=$('#schedTask').value,days=$$('#schedDays input:checked').map(x=>Number(x.value)),assigneeIds=$$('#schedAssignees input:checked').map(x=>x.value);if(!taskId)return;if(!days.length){toast('Choose at least one day');return}if(!plannerTimesDraft.length){toast('Add at least one time');return}state.schedule.push({id:uid('sched_'),taskId,mode:$('#schedMode').value,days,times:[...plannerTimesDraft],repeat:$('#schedRepeat').value,assigneeIds,notify:$('#schedNotify').checked,note:$('#schedNote').value.trim(),startDate:new Date(($('#schedStart').value||dateKey(new Date()))+'T12:00:00').toISOString()});state.plannerOffset=0;save();$('#plannerAddModal').classList.add('hidden');renderAll();toast('Added to HouseMade Planner');if(state.settings.sound)chime('pop')};
$('#addMember').onclick=()=>{const name=$('#memberName').value.trim();if(!name){toast('Add a name first');return}state.members.push({id:uid('member_'),name,channel:$('#memberChannel').value,contact:$('#memberContact').value.trim()});$('#memberName').value='';$('#memberContact').value='';save();renderAll();toast(`${name} added`);if(state.settings.sound)chime('pop')};
$('#newTask').onclick=()=>{const t={id:uid('task_'),name:'Custom task',icon:'sparkle',color:'#B59EE2',quick:[],deep:[]};state.library.push(t);save();renderTasks();editTask(t.id)};
$('#addPreset').onclick=()=>{const v=$('#newPreset').value.trim();if(!v)return;if(!state.presetItems.some(x=>x.toLowerCase()===v.toLowerCase()))state.presetItems.push(v);$('#newPreset').value='';save();renderPresetLibrary();toast('Added to master task library')};
$('#saveSettings').onclick=()=>{state.profile.firstName=$('#settingsName').value.trim()||state.profile.firstName;state.householdName=$('#settingsHouse').value.trim()||'Our House';state.settings.musicUrl=$('#musicUrl').value.trim();state.settings.defaultTimer=Math.max(1,Number($('#defaultTimer').value)||15);save();renderSettings();toast('Settings saved');startGreeting()};
$('#soundToggle').onclick=()=>{state.settings.sound=!state.settings.sound;save();renderSettings();if(state.settings.sound)chime('shimmer')};$('#themeToggle').onclick=()=>{state.settings.night=!state.settings.night;save();renderSettings()};$('#lockNow').onclick=()=>{if(!state.profile.pinHash){toast('Set a PIN during setup to use Lock now');return}sessionStorage.removeItem('hm-unlocked');showLock()};

function editTask(id){const t=getTask(id);if(!t)return;$('#editTaskId').value=id;$('#editTaskName').value=t.name;$('#editColor').value=t.color;$('#editHeading').textContent=t.name;renderIconPicker(t.icon);renderPresetGrid('quick',t);renderPresetGrid('deep',t);$('#editQuick').value='';$('#editDeep').value='';$('#editTaskModal').classList.remove('hidden')}
function renderIconPicker(active){const wrap=$('#iconPicker');wrap.innerHTML='';ICON_KEYS.forEach(k=>{const b=document.createElement('button');b.className='icon-choice'+(k===active?' active':'');b.dataset.icon=k;b.innerHTML=iconMarkup(k);b.onclick=()=>{$$('.icon-choice').forEach(x=>x.classList.remove('active'));b.classList.add('active')};wrap.appendChild(b)})}
function renderPresetGrid(mode,t){const wrap=$(`#${mode}Presets`);wrap.innerHTML='';state.presetItems.forEach(item=>{const b=document.createElement('button');b.className='preset-option'+(t[mode].includes(item)?' selected':'');b.dataset.item=item;b.innerHTML=`<span class="preset-check">${t[mode].includes(item)?'✓':''}</span><span></span>`;b.lastElementChild.textContent=item;b.onclick=()=>{b.classList.toggle('selected');b.querySelector('.preset-check').textContent=b.classList.contains('selected')?'✓':'';updatePresetCount(mode)};wrap.appendChild(b)});updatePresetCount(mode)}
function updatePresetCount(mode){$(`#${mode}Count`).textContent=`${$$(`#${mode}Presets .selected`).length} selected`}
$('#closeEdit').onclick=()=>$('#editTaskModal').classList.add('hidden');
$('#saveTaskEdit').onclick=()=>{const t=getTask($('#editTaskId').value);if(!t)return;t.name=$('#editTaskName').value.trim()||t.name;t.color=$('#editColor').value;t.icon=$('.icon-choice.active')?.dataset.icon||t.icon;['quick','deep'].forEach(mode=>{const selected=$$(`#${mode}Presets .selected`).map(b=>b.dataset.item);const customs=$(`#edit${mode[0].toUpperCase()+mode.slice(1)}`).value.split('\n').map(x=>x.trim()).filter(Boolean);t[mode]=[...new Set([...selected,...customs])]});save();$('#editTaskModal').classList.add('hidden');renderAll();toast('Task profile saved');if(state.settings.sound)chime('pop')};

function openTask(item,date,time=null){currentTask={...item,date:new Date(date),occurrenceTime:time||scheduleTimes(item)[0]||''};currentMode=item.mode||'quick';timer.selected=state.settings.defaultTimer||15;resetTimer();const t=getTask(item.taskId);$('#taskTitle').textContent=t.name;$('#taskMaster').style.setProperty('--task',t.color);$('#taskMaster').innerHTML=iconMarkup(t.icon);$('#taskSheet').style.setProperty('--task',t.color);$$('.mode-tab').forEach(b=>b.classList.toggle('active',b.dataset.mode===currentMode));renderTaskMode();newQuote();$('#taskModal').classList.remove('hidden')}
function renderTaskMode(){const t=getTask(currentTask.taskId),rec=completionFor(currentTask,currentTask.date,currentMode),items=t[currentMode];$('#taskModeLabel').textContent=currentMode==='deep'?'DEEP CLEAN':'QUICK CLEAN';$('#taskProgressText').textContent=`${rec.done.length} of ${items.length} complete`;const wrap=$('#subtasks');wrap.innerHTML='';items.forEach((name,i)=>{const done=rec.done.includes(name);const b=document.createElement('button');b.className='subtask'+(done?' done':'');b.style.setProperty('--task',t.color);b.innerHTML=`<span class="subtask-circle">${done?'✓':''}</span><span></span>`;b.lastElementChild.textContent=name;b.onclick=()=>toggleSubtask(name,b);wrap.appendChild(b)});$('#taskMaster').classList.toggle('gold',!!rec.all);$('#startTaskText').textContent=timer.running?'Pause timer':'Let’s get this house made'}
$$('.mode-tab').forEach(b=>b.onclick=()=>{currentMode=b.dataset.mode;$$('.mode-tab').forEach(x=>x.classList.toggle('active',x===b));renderTaskMode();newQuote();if(state.settings.sound)chime('soft')});
function toggleSubtask(name,button){const key=completionKey(currentTask,currentTask.date,currentMode,currentTask.occurrenceTime),t=getTask(currentTask.taskId),rec=state.completions[key]||{done:[],all:false};const set=new Set(rec.done);const was=set.has(name);was?set.delete(name):set.add(name);rec.done=[...set];rec.all=t[currentMode].length>0&&t[currentMode].every(x=>set.has(x));state.completions[key]=rec;save();if(!was&&state.settings.sound)chime('pop');renderTaskMode();renderPlanner();renderUpNext();renderProgressBoard();renderPromptQueue();updateNotificationDot();if(rec.all&&!was)celebrateCompletion(t)}
function newQuote(){const q=QUOTES[Math.floor(Math.random()*QUOTES.length)];$('#quoteText').textContent=q;const dust=$('#quoteDust');dust.classList.remove('quote-dust');void dust.offsetWidth;dust.classList.add('quote-dust')}
$('#anotherQuote').onclick=newQuote;$('#closeTask').onclick=()=>{$('#taskModal').classList.add('hidden');stopTimer(false)};
function celebrateCompletion(task){const buttons=$$('#subtasks .subtask');buttons.forEach((b,i)=>setTimeout(()=>{b.classList.add('celebrate');setTimeout(()=>b.classList.remove('celebrate'),550);if(state.settings.sound&&i%2===0)chime('soft')},i*110));setTimeout(()=>{$('#taskMaster').classList.add('gold');if(state.settings.sound)chime('win');setTimeout(()=>showCompletion(task),500)},buttons.length*110+250)}
function showCompletion(task){$('#completionRoom').textContent=`${task.name} complete!`;$('#completionQuote').textContent=QUOTES[Math.floor(Math.random()*QUOTES.length)];createConfetti();$('#completionOverlay').classList.remove('hidden')}
function createConfetti(){const wrap=$('#confettiField');wrap.innerHTML='';const colors=['#B59EE2','#E0B44D','#F3A7B8','#86C9D8','#9FD6C1','#FFFFFF'];for(let i=0;i<70;i++){const p=document.createElement('i');p.style.left=`${Math.random()*100}%`;p.style.setProperty('--c',colors[Math.floor(Math.random()*colors.length)]);p.style.setProperty('--dur',`${2.4+Math.random()*2}s`);p.style.setProperty('--delay',`${Math.random()*.8}s`);p.style.setProperty('--drift',`${-100+Math.random()*200}px`);wrap.appendChild(p)}}
$('#completionClose').onclick=()=>{$('#completionOverlay').classList.add('hidden');$('#taskModal').classList.add('hidden');renderAll()};

$$('.timer-presets button').forEach(b=>b.onclick=()=>{timer.selected=Number(b.dataset.minutes);$$('.timer-presets button').forEach(x=>x.classList.toggle('active',x===b));resetTimer();if(state.settings.sound)chime('soft')});
function resetTimer(){stopTimer(false);timer.total=timer.selected*60;timer.remaining=timer.total;updateTimerDisplay()}
function updateTimerDisplay(){const m=Math.floor(timer.remaining/60),s=timer.remaining%60;$('#timerReadout').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;const p=timer.total?1-timer.remaining/timer.total:0;$('#timerRing').style.strokeDashoffset=314.16*p;$('#startTaskText').textContent=timer.running?'Pause timer':'Let’s get this house made'}
function startTimer(){if(timer.running){stopTimer(true);return}if(timer.remaining<=0)resetTimer();timer.running=true;if(state.settings.sound)chime('start');timer.id=setInterval(()=>{timer.remaining--;if(timer.remaining<=5&&timer.remaining>0&&state.settings.sound)chime('tick');if(timer.remaining<=0){timer.remaining=0;stopTimer(false);updateTimerDisplay();if(state.settings.sound)chime('win');toast('Time! Look what you got done ✦');showLocalNotification('HouseMade timer','Time! Your focus session is complete.');return}updateTimerDisplay()},1000);updateTimerDisplay()}
function stopTimer(keep=true){if(timer.id)clearInterval(timer.id);timer.id=null;timer.running=false;if(!keep&&timer.total===0){timer.total=timer.selected*60;timer.remaining=timer.total}updateTimerDisplay()}
$('#startTask').onclick=()=>{const starting=!timer.running;if(starting&&state.settings.musicUrl)window.open(state.settings.musicUrl,'_blank','noopener,noreferrer');startTimer()};$('#taskMusic').onclick=()=>{if(!state.settings.musicUrl){toast('Add a playlist link in Settings');return}window.open(state.settings.musicUrl,'_blank','noopener,noreferrer')};$('#taskReminder').onclick=()=>{const t=getTask(currentTask.taskId);showLocalNotification('HouseMade',`${t.name} is waiting for you.`);toast('Reminder notification sent')};

function openReminder(member,context=null){currentMember=member;currentPromptContext=context;$('#reminderMember').textContent=member.name;generateReminder();$('#reminderModal').classList.remove('hidden')}
function assignedTaskName(member){const item=state.schedule.find(s=>scheduleAssignees(s).includes(member.id));return getTask(item?.taskId)?.name||'HouseMade chore'}
function generateReminder(){const t=currentPromptContext?.taskName||assignedTaskName(currentMember),fn=REMINDER_TEMPLATES[Math.floor(Math.random()*REMINDER_TEMPLATES.length)],when=currentPromptContext?.date?` ${currentPromptContext.date.toLocaleDateString(undefined,{weekday:'long'})} at ${currentPromptContext.time}.`:'';$('#reminderText').value=fn(currentMember.name,t)+when}
$('#regenReminder').onclick=generateReminder;$('#closeReminder').onclick=()=>{$('#reminderModal').classList.add('hidden');currentPromptContext=null};$('#copyReminder').onclick=async()=>{await navigator.clipboard.writeText($('#reminderText').value);if(currentPromptContext?.queueId){state.promptStatus[currentPromptContext.queueId]='copied';save();renderPromptQueue()}toast('Reminder copied')};$('#sendReminder').onclick=()=>{const text=$('#reminderText').value,m=currentMember;if(currentPromptContext?.queueId){state.promptStatus[currentPromptContext.queueId]='prepared';save();renderPromptQueue()}if(m.channel==='sms'&&m.contact){location.href=`sms:${encodeURIComponent(m.contact)}?&body=${encodeURIComponent(text)}`;return}if(m.channel==='email'&&m.contact){location.href=`mailto:${encodeURIComponent(m.contact)}?subject=${encodeURIComponent('HouseMade chore reminder')}&body=${encodeURIComponent(text)}`;return}navigator.clipboard.writeText(text);toast(m.channel==='alexa'?'Alexa-ready prompt copied':'Reminder copied')};$('#setLocalReminder').onclick=async()=>{const minutes=Math.max(1,Number($('#reminderDelay').value)||10);await ensureNotifications();setTimeout(()=>showLocalNotification('HouseMade reminder',$('#reminderText').value),minutes*60000);toast(`Local reminder set for ${minutes} min`) };

async function ensureNotifications(){if(!('Notification'in window)){toast('Notifications are not supported on this device');return false}if(Notification.permission==='granted'){state.settings.notifications=true;save();return true}const p=await Notification.requestPermission();state.settings.notifications=p==='granted';save();renderSettings();return p==='granted'}
async function showLocalNotification(title,body){if(!(await ensureNotifications()))return;try{const reg=await navigator.serviceWorker?.ready;if(reg?.showNotification)await reg.showNotification(title,{body,icon:'./icon-192.png',badge:'./icon-192.png',tag:'housemade-reminder',renotify:true});else new Notification(title,{body,icon:'./icon-192.png'})}catch{try{new Notification(title,{body,icon:'./icon-192.png'})}catch{}}}
$('#enableNotifications').onclick=async()=>{if(await ensureNotifications()){toast('HouseMade notifications enabled');showLocalNotification('HouseMade','Notifications are ready ✦')}};$('#notificationBell').onclick=async()=>{if(await ensureNotifications())showLocalNotification('HouseMade','Your next chore is waiting when you’re ready.')};$('#testNotification').onclick=async()=>{if(await ensureNotifications())showLocalNotification('HouseMade','Notifications are ready. Tiny victory unlocked ✦')};
let reminderChecker=null;function startReminderChecker(){if(reminderChecker)return;checkScheduledReminders();reminderChecker=setInterval(checkScheduledReminders,30000)}
function checkScheduledReminders(){if(!state.settings.notifications||Notification.permission!=='granted')return;const now=new Date(),today=dateKey(now),minutes=now.getHours()*60+now.getMinutes();state.schedule.filter(s=>s.notify!==false&&occursOn(s,now)).forEach(item=>{scheduleTimes(item).forEach(time=>{const[h,m]=time.split(':').map(Number),target=h*60+m,key=`${item.id}:${today}:${time}`;if(minutes>=target&&minutes<target+3&&!state.notificationHistory[key]&&!isComplete(item,now,item.mode,time)){const t=getTask(item.taskId),names=scheduleAssignees(item).map(id=>state.members.find(x=>x.id===id)?.name).filter(Boolean);showLocalNotification(names.length?`HouseMade · ${names.join(', ')}`:'HouseMade',`${t.name} · ${item.mode==='deep'?'Deep Clean':'Quick Clean'} is on the planner for ${time}.`);state.notificationHistory[key]=Date.now();save()}})})}

function chime(kind){try{const c=new(window.AudioContext||window.webkitAudioContext)();const now=c.currentTime;const seq=kind==='win'?[523,659,784,1046]:kind==='shimmer'?[784,988,1175,1568]:kind==='start'?[392,523,659]:kind==='error'?[260,210]:kind==='tick'?[740]:kind==='soft'?[620]:[660,880];seq.forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.type=kind==='win'||kind==='shimmer'?'sine':'triangle';o.frequency.setValueAtTime(f,now+i*.075);g.gain.setValueAtTime(.0001,now+i*.075);g.gain.exponentialRampToValueAtTime(kind==='tick'?.025:.05,now+i*.075+.012);g.gain.exponentialRampToValueAtTime(.0001,now+i*.075+.16);o.connect(g);g.connect(c.destination);o.start(now+i*.075);o.stop(now+i*.075+.18)})}catch{}}

function showSelfCare(){const item=SELF_CARE[Math.floor(Math.random()*SELF_CARE.length)];$('#selfCareIcon').textContent=item.icon;$('#selfCareTitle').textContent=item.title;$('#selfCareText').textContent=item.text;const sheet=$('.self-care-sheet');sheet.classList.remove('reveal');void sheet.offsetWidth;sheet.classList.add('reveal');if(state.settings.sound)chime('shimmer')}
$('#yourButton').onclick=()=>{$('#selfCareModal').classList.remove('hidden');showSelfCare()};$('#anotherSelfCare').onclick=showSelfCare;$('#closeSelfCare').onclick=()=>$('#selfCareModal').classList.add('hidden');

const game={grid:18,stage:0,score:0,collected:0,snake:[],dir:{x:1,y:0},nextDir:{x:1,y:0},inputQueue:[],mess:null,obstacles:[],running:false,timer:null,stageClear:false,gameOver:false};
function gameCell(){return $('#gameCanvas').width/game.grid}
function sameCell(a,b){return a&&b&&a.x===b.x&&a.y===b.y}
function gameOccupied(p){return game.snake.some(x=>sameCell(x,p))||game.obstacles.some(x=>sameCell(x,p))||sameCell(game.mess,p)}
function randomGameCell(){let p,guard=0;do{p={x:1+Math.floor(Math.random()*(game.grid-2)),y:1+Math.floor(Math.random()*(game.grid-2))};guard++}while(gameOccupied(p)&&guard<300);return p}
function spawnGameMess(){game.mess=randomGameCell()}
function buildObstacles(count){game.obstacles=[];for(let i=0;i<count;i++){const p=randomGameCell();if(!game.snake.some(x=>sameCell(x,p)))game.obstacles.push(p)}}
function resetGameStage(){const stage=GAME_STAGES[game.stage];game.snake=[{x:4,y:9},{x:3,y:9},{x:2,y:9}];game.dir={x:1,y:0};game.nextDir={x:1,y:0};game.inputQueue=[];game.collected=0;game.stageClear=false;game.gameOver=false;game.mess=null;buildObstacles(stage.obstacles);spawnGameMess();$('#gameStage').textContent=stage.name;updateGameHud();drawGame()}
function updateGameHud(){const stage=GAME_STAGES[game.stage];$('#gameScore').textContent=String(game.score).padStart(3,'0');$('#gameMess').textContent=`${game.collected}/${stage.target}`}
function drawRoundedRect(ctx,x,y,w,h,r){const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.lineTo(x+w-rr,y);ctx.quadraticCurveTo(x+w,y,x+w,y+rr);ctx.lineTo(x+w,y+h-rr);ctx.quadraticCurveTo(x+w,y+h,x+w-rr,y+h);ctx.lineTo(x+rr,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-rr);ctx.lineTo(x,y+rr);ctx.quadraticCurveTo(x,y,x+rr,y);ctx.closePath();ctx.fill()}
function drawGame(){const c=$('#gameCanvas'),ctx=c.getContext('2d'),cell=gameCell(),stage=GAME_STAGES[game.stage];ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#2D2738';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='rgba(255,255,255,.035)';ctx.lineWidth=1;for(let i=0;i<=game.grid;i++){ctx.beginPath();ctx.moveTo(i*cell,0);ctx.lineTo(i*cell,c.height);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*cell);ctx.lineTo(c.width,i*cell);ctx.stroke()}ctx.fillStyle=stage.accent+'38';ctx.fillRect(0,0,c.width,cell*.42);ctx.fillRect(0,c.height-cell*.42,c.width,cell*.42);ctx.fillRect(0,0,cell*.42,c.height);ctx.fillRect(c.width-cell*.42,0,cell*.42,c.height);ctx.fillStyle=stage.accent;ctx.globalAlpha=.62;const mid=c.width/2;ctx.font=`${cell*.62}px ui-monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('↕',mid,cell*.48);ctx.fillText('↕',mid,c.height-cell*.48);ctx.save();ctx.translate(cell*.48,c.height/2);ctx.rotate(Math.PI/2);ctx.fillText('↕',0,0);ctx.restore();ctx.save();ctx.translate(c.width-cell*.48,c.height/2);ctx.rotate(Math.PI/2);ctx.fillText('↕',0,0);ctx.restore();ctx.globalAlpha=1;
 game.obstacles.forEach((o,i)=>{const x=o.x*cell+2,y=o.y*cell+2;ctx.fillStyle=i%2?'#6B5C78':'#776886';drawRoundedRect(ctx,x,y,cell-4,cell-4,4);ctx.fillStyle='rgba(255,255,255,.18)';ctx.fillRect(x+4,y+4,cell-12,3)});
 if(game.mess){const x=(game.mess.x+.5)*cell,y=(game.mess.y+.5)*cell;ctx.fillStyle='#F5C45F';ctx.beginPath();ctx.arc(x,y,cell*.23,0,Math.PI*2);ctx.fill();ctx.fillStyle='#F38CA7';ctx.beginPath();ctx.arc(x-cell*.16,y+cell*.13,cell*.09,0,Math.PI*2);ctx.fill();ctx.fillStyle='#A6D8CD';ctx.fillRect(x+cell*.07,y-cell*.22,cell*.16,cell*.12)}
 game.snake.slice().reverse().forEach((p,rev)=>{const index=game.snake.length-1-rev,x=(p.x+.5)*cell,y=(p.y+.5)*cell,head=index===0;ctx.fillStyle=head?'#FFFFFF':`rgba(181,158,226,${.5+.5*(1-index/Math.max(1,game.snake.length))})`;ctx.beginPath();ctx.arc(x,y,head?cell*.34:cell*.27,0,Math.PI*2);ctx.fill();if(head){ctx.strokeStyle=stage.accent;ctx.lineWidth=2;for(let j=-1;j<=1;j++){ctx.beginPath();ctx.moveTo(x-cell*.1,y+j*3);ctx.lineTo(x-cell*.42,y+j*6);ctx.stroke()}}});}
function setGameDirection(name){const dirs={up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}},n=dirs[name];if(!n)return;const reference=game.inputQueue.length?game.inputQueue[game.inputQueue.length-1]:game.nextDir;const current=reference||game.dir;if(n.x===current.x&&n.y===current.y)return;if(n.x===-current.x&&n.y===-current.y)return;if(game.inputQueue.length<3)game.inputQueue.push(n);game.nextDir=game.inputQueue[0]||n}
function stopGameLoop(){if(game.timer)clearInterval(game.timer);game.timer=null;game.running=false;$('#pauseGame').textContent='PAUSE'}
function runGameLoop(){stopGameLoop();game.running=true;$('#pauseGame').textContent='PAUSE';game.timer=setInterval(gameTick,GAME_STAGES[game.stage].speed)}
function gameTick(){if(game.inputQueue.length)game.dir=game.inputQueue.shift();else game.dir=game.nextDir;game.nextDir=game.inputQueue[0]||game.dir;const head=game.snake[0],next={x:(head.x+game.dir.x+game.grid)%game.grid,y:(head.y+game.dir.y+game.grid)%game.grid};if(game.obstacles.some(x=>sameCell(x,next))||game.snake.some(x=>sameCell(x,next))){loseGame();return}game.snake.unshift(next);if(sameCell(next,game.mess)){game.collected++;game.score+=10+game.stage*3;state.game.totalTrash=(state.game.totalTrash||0)+1;state.game.bestScore=Math.max(state.game.bestScore||0,game.score);save();if(state.settings.sound)chime('pop');if(game.collected>=GAME_STAGES[game.stage].target){clearGameStage();return}spawnGameMess()}else game.snake.pop();updateGameHud();drawGame()}
function showGameMessage(title,text,button){$('#gameMessage b').textContent=title;$('#gameMessage span').textContent=text;$('#startGame').textContent=button;$('#gameMessage').classList.remove('hidden')}
function clearGameStage(){stopGameLoop();game.stageClear=true;drawGame();if(state.settings.sound)chime('win');state.game.bestStage=Math.max(state.game.bestStage||1,game.stage+1);save();if(game.stage===GAME_STAGES.length-1){game.gameOver=true;showGameMessage('Whole house cleared!','You beat every room. The mess has officially filed a complaint.','Play again')}else showGameMessage(`${GAME_STAGES[game.stage].name} cleared!`,`Next up: ${GAME_STAGES[game.stage+1].name}. It gets a little faster and a little messier.`,'Next room')}
function loseGame(){stopGameLoop();game.gameOver=true;if(state.settings.sound)chime('error');showGameMessage('Furniture!','You hit something you were definitely meant to clean around. Try the room again.','Try again')}
function startGameAction(){if(game.stageClear&&game.stage<GAME_STAGES.length-1){game.stage++;resetGameStage()}else if(game.gameOver&&game.stage===GAME_STAGES.length-1&&game.stageClear){game.stage=0;game.score=0;resetGameStage()}else if(game.gameOver){resetGameStage()}$('#gameMessage').classList.add('hidden');runGameLoop()}
$('#openGame').onclick=()=>{$('#gameModal').classList.remove('hidden');game.stage=0;game.score=0;resetGameStage();showGameMessage('Clean Break','Collect every bit of mess. Avoid the furniture and your own trail. Escape through any edge to wrap around to the opposite side.','Start');if(state.settings.sound)chime('start')};
$('#closeGame').onclick=()=>{stopGameLoop();$('#gameModal').classList.add('hidden')};$('#startGame').onclick=startGameAction;$('#pauseGame').onclick=()=>{if(game.running){stopGameLoop();showGameMessage('Paused','The mess will wait. It is annoyingly patient.','Resume')}else{$('#gameMessage').classList.add('hidden');runGameLoop()}};$$('.direction-pad button').forEach(b=>{const release=()=>b.classList.remove('pressed');b.addEventListener('pointerdown',e=>{e.preventDefault();setGameDirection(b.dataset.dir);b.classList.add('pressed');try{b.setPointerCapture(e.pointerId)}catch{}});b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);b.addEventListener('contextmenu',e=>e.preventDefault())});

$('#closeReminder').addEventListener('click',()=>{});document.addEventListener('keydown',e=>{if(!$('#gameModal').classList.contains('hidden')){const map={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};if(map[e.key]){e.preventDefault();setGameDirection(map[e.key]);return}}if(e.key==='Escape'){$$('.modal:not(.hidden)').forEach(m=>m.classList.add('hidden'));$('#completionOverlay').classList.add('hidden');if(!$('#gameModal').classList.contains('hidden')){stopGameLoop();$('#gameModal').classList.add('hidden')}}});
window.addEventListener('online',()=>toast('Back online'));window.addEventListener('offline',()=>toast('Offline — HouseMade still works'));
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
